package glitch

import data.glitch_lib

# Weak encryption algorithms and protocols
weak_algorithms := {"des", "3des", "rc4", "aes-128", "md5", "sha1", "md5_crypt"}
weak_protocols := {"ssl", "ssl2", "ssl3", "tls1", "tls1.0", "tls1.1"}

# Check for weak algorithm in string value
check_weak_algorithm(value) {
    value.ir_type == "String"
    algorithm := lower(value.value)
    weak_algorithms[_] == algorithm
} else {
    value.ir_type == "String"
    algorithm := lower(value.value)
    contains(algorithm, weak_algorithms[_])
}

# Check for weak protocol in string value
check_weak_protocol(value) {
    value.ir_type == "String"
    protocol := lower(value.value)
    weak_protocols[_] == protocol
} else {
    value.ir_type == "String"
    protocol := lower(value.value)
    contains(protocol, weak_protocols[_])
}

# Check for weak cipher suite patterns
check_weak_cipher_suite(value) {
    value.ir_type == "String"
    cipher := lower(value.value)
    regex.match(".*(?:rc4|md5|sha1|cbc).*", cipher)
}

# Main detection rule for weak encryption algorithms/protocols
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check attributes
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    # Check for weak algorithm or protocol
    check_weak_algorithm(attr.value) or check_weak_protocol(attr.value) or check_weak_cipher_suite(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of weak encryption algorithm or protocol - Use strong cryptographic algorithms (AES-256, ChaCha20) and protocols (TLS 1.2+). (CWE-326)"
    }
}

# Check for weak encryption in function calls (e.g., hash filters in Ansible)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check all function calls
    walk(parent, [path, node])
    node.ir_type == "FunctionCall"

    # Check if function name contains weak algorithm
    func_name := lower(node.name)
    contains(func_name, weak_algorithms[_])

    result := {
        "type": "sec_weak_crypt",
        "element": node,
        "path": parent.path,
        "description": "Use of weak encryption algorithm or protocol - Use strong cryptographic algorithms (AES-256, ChaCha20) and protocols (TLS 1.2+). (CWE-326)"
    }
}

# Check for weak encryption in variable assignments
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check all variables
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    # Check if variable value contains weak algorithm
    check_weak_algorithm(var.value) or check_weak_protocol(var.value) or check_weak_cipher_suite(var.value)

    result := {
        "type": "sec_weak_crypt",
        "element": var,
        "path": parent.path,
        "description": "Use of weak encryption algorithm or protocol - Use strong cryptographic algorithms (AES-256, ChaCha20) and protocols (TLS 1.2+). (CWE-326)"
    }
}

